/**
 * Amazon
 *
 * The mouth of the Amazon river (coordinates 0.138050, -50.466245, 200 km wide).
 * Ported from the Alpha 21 map script to the current map API. The heightmap,
 * terrain tilemap and palette of the original map are kept (encoded below);
 * vegetation and fauna come from the Endovelico "generic/amazon" biome.
 *
 * Generated by tools/make_amazon_map.py - edit that script, not this file.
 */

import { addAnimals, addBerries, addDecoration, addFish, addForests, addLayeredPatches, addMetal, addStone,
	addStragglerTrees } from "maps/random/rmgen2/gaia.js";
import { addElements, createBases, initTileClasses } from "maps/random/rmgen2/setup.js";

Engine.LoadLibrary("rmgen");
Engine.LoadLibrary("rmgen-common");
Engine.LoadLibrary("rmbiome");

const HEIGHTMAP_SIZE = 320;
const HEIGHT_MIN = -20.0;
const HEIGHT_MAX = 7.0;
const ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-_";

/** Terrain palette of the original map, indexed by the tilemap. */
const TILE_PALETTE = ["tropic_cliff_grass", "tropic_plants", "tropic_grass_c", "tropic_grass_plants", "tropic_dirt_a", "tropic_beach_dry", "tropic_dirt_a_plants", "tropic_cliff_a"];

/** Player start positions, in heightmap coordinates. */
const SINGLE_BASES = [
	[90, 115], [240, 157], [35, 155], [140, 25],
	[260, 75], [160, 285], [105, 220], [185, 90]
];

/** Team start areas, in heightmap coordinates. */
const STRONGHOLD_BASES = [
	[80, 240],
	[190, 60]
];

/** Amazonian fauna of this mod. */
const fauna = {
	"herd": "gaia/fauna_peccary",
	"tapir": "gaia/fauna_tapir_lowland",
	"deer": "gaia/fauna_brocket_red",
	"birds": ["gaia/fauna_curassow", "gaia/fauna_curassow_female", "gaia/fauna_tinamou", "gaia/fauna_guan_crested"],
	"smallGame": ["gaia/fauna_paca", "gaia/fauna_tapeti"],
	"monkeys": ["gaia/fauna_monkey_howler", "gaia/fauna_monkey_spider"],
	"forestDwellers": ["gaia/fauna_coati", "gaia/fauna_tamandua", "gaia/fauna_opossum", "gaia/fauna_iguana_green"],
	"anteater": "gaia/fauna_anteater_02",
	"riverbank": ["gaia/fauna_caiman", "gaia/fauna_otter_tropical", "gaia/fauna_boa_constrictor", "gaia/fauna_toad_cane"],
	"bigCats": ["gaia/fauna_jaguar_02", "gaia/fauna_panther_black"],
	"smallCats": ["gaia/fauna_ocelot", "gaia/fauna_margay", "gaia/fauna_jaguarundi"],
	"flyingBird": "birds/fauna_parrot"
};

export function* generateMap(mapSettings)
{
	setBiome("generic/amazon");

	g_Gaia.mainHuntableAnimal = fauna.herd;
	g_Gaia.secondaryHuntableAnimal = fauna.tapir;
	g_Gaia.startingAnimal = "gaia/fauna_curassow";
	g_Gaia.predator = fauna.bigCats[0];
	g_Gaia.smallAnimal = "gaia/fauna_paca";

	globalThis.g_Map = new RandomMap(0, g_Terrains.mainTerrain);
	const mapSize = g_Map.getSize();

	initTileClasses();

	// Heightmap coordinates per map vertex, as in the original paintHeightmap().
	const hmScale = HEIGHTMAP_SIZE / (mapSize + 1);

	g_Map.log("Decoding heightmap");
	const heights = new Float32Array(HEIGHTMAP_SIZE * HEIGHTMAP_SIZE);
	for (let i = 0; i < heights.length; ++i)
	{
		const q = ALPHABET.indexOf(HEIGHTMAP[2 * i]) * 64 + ALPHABET.indexOf(HEIGHTMAP[2 * i + 1]);
		heights[i] = HEIGHT_MIN + q / 4095 * (HEIGHT_MAX - HEIGHT_MIN);
	}
	const hmAt = (x, y) => heights[
		Math.max(0, Math.min(HEIGHTMAP_SIZE - 1, x)) * HEIGHTMAP_SIZE +
		Math.max(0, Math.min(HEIGHTMAP_SIZE - 1, y))];

	g_Map.log("Painting heightmap and terrain");
	const terrains = TILE_PALETTE.map(name => createTerrain(name));
	for (let x = 0; x <= mapSize; ++x)
		for (let y = 0; y <= mapSize; ++y)
		{
			const hx = x * hmScale;
			const hy = y * hmScale;
			const ix = Math.floor(hx);
			const iy = Math.floor(hy);
			const fx = hx - ix;
			const fy = hy - iy;
			const height =
				hmAt(ix, iy) * (1 - fx) * (1 - fy) +
				hmAt(ix + 1, iy) * fx * (1 - fy) +
				hmAt(ix, iy + 1) * (1 - fx) * fy +
				hmAt(ix + 1, iy + 1) * fx * fy;

			// Heights grow with the map size, like the original script.
			const position = new Vector2D(x, y);
			g_Map.setHeight(position, height / hmScale);

			if (x < mapSize && y < mapSize)
			{
				const tile = ALPHABET.indexOf(TILEMAP[Math.min(HEIGHTMAP_SIZE - 1, ix) * HEIGHTMAP_SIZE + Math.min(HEIGHTMAP_SIZE - 1, iy)]);
				terrains[tile].place(position);
			}
		}
	yield 20;

	g_Map.log("Smoothing heightmap");
	createArea(
		new MapBoundsPlacer(),
		new SmoothingPainter(1, scaleByMapSize(0.1, 0.4), 1));
	yield 30;

	g_Map.log("Marking water and land");
	paintTileClassBasedOnHeight(-Infinity, -1, Elevation_ExcludeMin_ExcludeMax, g_TileClasses.water);
	paintTileClassBasedOnHeight(-1, Infinity, Elevation_ExcludeMin_ExcludeMax, g_TileClasses.land);
	yield 40;

	if (!mapSettings.Nomad)
	{
		g_Map.log("Placing players");
		createBases(placePlayersAtBases(hmScale), false);
	}
	yield 50;

	addElements([
		{
			"func": addLayeredPatches,
			"avoid": [
				g_TileClasses.dirt, 5,
				g_TileClasses.forest, 2,
				g_TileClasses.mountain, 2,
				g_TileClasses.player, 12,
				g_TileClasses.water, 3
			],
			"sizes": ["normal"],
			"mixes": ["normal"],
			"amounts": ["many"]
		},
		{
			"func": addDecoration,
			"avoid": [
				g_TileClasses.forest, 2,
				g_TileClasses.mountain, 2,
				g_TileClasses.player, 12,
				g_TileClasses.water, 3
			],
			"sizes": ["normal"],
			"mixes": ["normal"],
			"amounts": ["many"]
		}
	]);
	yield 60;

	addElements(shuffleArray([
		{
			"func": addMetal,
			"avoid": [
				g_TileClasses.berries, 5,
				g_TileClasses.forest, 3,
				g_TileClasses.mountain, 2,
				g_TileClasses.player, 30,
				g_TileClasses.rock, 10,
				g_TileClasses.metal, 20,
				g_TileClasses.water, 3
			],
			"sizes": ["normal"],
			"mixes": ["same"],
			"amounts": ["normal", "many"]
		},
		{
			"func": addStone,
			"avoid": [
				g_TileClasses.berries, 5,
				g_TileClasses.forest, 3,
				g_TileClasses.mountain, 2,
				g_TileClasses.player, 30,
				g_TileClasses.rock, 20,
				g_TileClasses.metal, 10,
				g_TileClasses.water, 3
			],
			"sizes": ["normal"],
			"mixes": ["same"],
			"amounts": ["normal", "many"]
		},
		{
			"func": addForests,
			"avoid": [
				g_TileClasses.berries, 5,
				g_TileClasses.forest, 18,
				g_TileClasses.metal, 3,
				g_TileClasses.mountain, 5,
				g_TileClasses.player, 20,
				g_TileClasses.rock, 3,
				g_TileClasses.water, 2
			],
			"sizes": ["normal"],
			"mixes": ["similar"],
			"amounts": ["tons"]
		}
	]));
	yield 70;

	addElements(shuffleArray([
		{
			"func": addBerries,
			"avoid": [
				g_TileClasses.berries, 30,
				g_TileClasses.forest, 5,
				g_TileClasses.metal, 10,
				g_TileClasses.mountain, 2,
				g_TileClasses.player, 20,
				g_TileClasses.rock, 10,
				g_TileClasses.water, 3
			],
			"sizes": ["normal"],
			"mixes": ["same"],
			"amounts": ["normal", "many"]
		},
		{
			"func": addAnimals,
			"avoid": [
				g_TileClasses.animals, 20,
				g_TileClasses.forest, 2,
				g_TileClasses.metal, 2,
				g_TileClasses.mountain, 1,
				g_TileClasses.player, 20,
				g_TileClasses.rock, 2,
				g_TileClasses.water, 3
			],
			"sizes": ["normal"],
			"mixes": ["same"],
			"amounts": ["many"]
		},
		{
			"func": addFish,
			"avoid": [
				g_TileClasses.fish, 12,
				g_TileClasses.player, 8
			],
			"stay": [g_TileClasses.water, 4],
			"sizes": ["normal"],
			"mixes": ["same"],
			"amounts": ["many"]
		},
		{
			"func": addStragglerTrees,
			"avoid": [
				g_TileClasses.berries, 5,
				g_TileClasses.forest, 7,
				g_TileClasses.metal, 2,
				g_TileClasses.mountain, 1,
				g_TileClasses.player, 12,
				g_TileClasses.rock, 2,
				g_TileClasses.water, 5
			],
			"sizes": ["normal"],
			"mixes": ["same"],
			"amounts": ["many"]
		}
	]));
	yield 75;

	g_Map.log("Placing Amazonian fauna");
	placeAmazonFauna();
	yield 85;

	g_Map.log("Adding lillies");
	createObjectGroupsDeprecated(
		new SimpleGroup(
			[
				new SimpleObject(g_Decoratives.lillies, 5, 12, 1, 4),
				new SimpleObject(g_Decoratives.reeds, 2, 5, 1, 4)
			],
			true,
			g_TileClasses.dirt),
		0,
		[
			stayClasses(g_TileClasses.water, 1),
			borderClasses(g_TileClasses.water, scaleByMapSize(2, 8), scaleByMapSize(2, 5))
		],
		scaleByMapSize(100, 2000),
		50);
	yield 90;

	placePlayersNomad(
		g_Map.createTileClass(),
		[
			stayClasses(g_TileClasses.land, 5),
			avoidClasses(
				g_TileClasses.forest, 2,
				g_TileClasses.rock, 4,
				g_TileClasses.metal, 4,
				g_TileClasses.berries, 2,
				g_TileClasses.animals, 2,
				g_TileClasses.water, 4)
		]);

	return g_Map;
}

/**
 * Start positions of the original map: one base per player picked at random,
 * or (sometimes, on larger maps with 2 teams) each team grouped around one of
 * the stronghold areas.
 */
function placePlayersAtBases(hmScale)
{
	const toTiles = base => new Vector2D(base[0], base[1]).div(hmScale).round();
	const teams = getTeamsArray();
	const numPlayers = getNumPlayers();

	if (randBool(1/3) && g_Map.getSize() >= 256 && teams.length >= 2 && teams.length < numPlayers &&
		teams.length <= STRONGHOLD_BASES.length)
	{
		const strongholds = shuffleArray(STRONGHOLD_BASES).map(toTiles);
		const playerIDs = [];
		const playerPosition = [];
		const radius = fractionToTiles(0.06);
		teams.forEach((team, t) => {
			const startAngle = randomAngle();
			team.forEach((playerID, i) => {
				playerIDs.push(playerID);
				playerPosition.push(team.length == 1 ? strongholds[t] :
					Vector2D.add(strongholds[t], new Vector2D(radius, 0).rotate(startAngle + 2 * Math.PI * i / team.length)).round());
			});
		});
		return { "playerIDs": playerIDs, "playerPosition": playerPosition };
	}

	const bases = shuffleArray(SINGLE_BASES).map(toTiles);
	const playerIDs = shuffleArray(getPlayerIDs());
	return { "playerIDs": playerIDs, "playerPosition": playerIDs.map((id, i) => bases[i]) };
}

function placeFaunaGroups(templates, min, max, spread, constraints, amount)
{
	for (const template of templates)
		createObjectGroupsDeprecated(
			new SimpleGroup([new SimpleObject(template, min, max, 0, spread)], true, g_TileClasses.animals),
			0,
			constraints,
			Math.round(amount / templates.length) || 1,
			50);
}

function placeAmazonFauna()
{
	const awayFromPlayers = distance => avoidClasses(
		g_TileClasses.player, distance,
		g_TileClasses.water, 2,
		g_TileClasses.forest, 0,
		g_TileClasses.rock, 2,
		g_TileClasses.metal, 2,
		g_TileClasses.animals, 8);
	const nearForest = [
		avoidClasses(g_TileClasses.player, 20, g_TileClasses.water, 2, g_TileClasses.animals, 6),
		borderClasses(g_TileClasses.forest, 2, 2)
	];
	const riverbank = [
		avoidClasses(g_TileClasses.player, 18, g_TileClasses.animals, 6),
		borderClasses(g_TileClasses.water, 4, 2)
	];

	// Red brocket deer and the lowland tapir walk the open ground between forests.
	placeFaunaGroups([fauna.deer], 2, 4, 3, awayFromPlayers(22), scaleByMapSize(4, 16));
	placeFaunaGroups([fauna.tapir], 1, 2, 2, awayFromPlayers(25), scaleByMapSize(3, 10));
	placeFaunaGroups([fauna.anteater], 1, 1, 1, awayFromPlayers(20), scaleByMapSize(2, 8));

	// Ground birds and small game, also near the bases as an early food source.
	placeFaunaGroups(fauna.birds, 2, 4, 2, awayFromPlayers(14), scaleByMapSize(8, 28));
	placeFaunaGroups(fauna.smallGame, 1, 3, 2, awayFromPlayers(14), scaleByMapSize(4, 16));

	// Canopy and forest-edge animals.
	placeFaunaGroups(fauna.monkeys, 3, 5, 3, nearForest, scaleByMapSize(4, 16));
	placeFaunaGroups(fauna.forestDwellers, 1, 2, 2, nearForest, scaleByMapSize(6, 20));

	// Caimans, otters, boas and cane toads along the rivers.
	placeFaunaGroups(fauna.riverbank, 1, 2, 2, riverbank, scaleByMapSize(8, 28));

	// Predators keep away from the starting bases.
	placeFaunaGroups(fauna.bigCats, 1, 1, 1, awayFromPlayers(40), scaleByMapSize(2, 7));
	placeFaunaGroups(fauna.smallCats, 1, 1, 1, awayFromPlayers(30), scaleByMapSize(3, 9));

	// Parrots flying over the forest.
	createObjectGroupsDeprecated(
		new SimpleGroup([new SimpleObject(fauna.flyingBird, 1, 2, 0, 4)], true),
		0,
		avoidClasses(g_TileClasses.player, 10),
		scaleByMapSize(4, 14),
		50);
}

